window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[100]={"id":"100","numero":100,"titre":"Céphalée aiguë et chronique","objectifs":[{"id":"100-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une céphalée aiguë et d’une céphalée chronique","contenu":"<p>Le diagnostic d'une <span class=\"kw-clinique\">céphalée</span> repose <strong>d'abord sur l'interrogatoire</strong>, l'examen clinique étant souvent normal y compris dans les causes graves. La démarche distingue la <span class=\"kw-def\">céphalée aiguë</span> (récente, &lt;<span class=\"kw-chiffre\"> 7 jours</span>, <span class=\"kw-alerte\">urgence</span> à explorer comme secondaire jusqu'à preuve du contraire) de la <span class=\"kw-def\">céphalée chronique</span> (<span class=\"kw-chiffre\">≥ 3 mois</span>, généralement primaire mais à explorer une fois pour éliminer une cause secondaire).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>3 dogmes pédagogiques.</strong> Toute <span class=\"kw-clinique\">céphalée</span> <span class=\"kw-alerte\">brutale</span> est explorée comme une <span class=\"kw-etio\">HSA anévrismale</span>. Toute céphalée <span class=\"kw-alerte\">progressive</span> est explorée comme une <span class=\"kw-etio\">HTIC</span>. Toute céphalée <span class=\"kw-alerte\">fébrile</span> est explorée comme une <span class=\"kw-etio\">méningite</span>.\n      </div>\n\n      <h4>Interrogatoire face à une <span class=\"kw-clinique\">céphalée</span> aiguë — 7 questions</h4>\n      <ul>\n        <li><strong>Avez-vous déjà eu ce type de mal de tête ?</strong> → caractère <span class=\"kw-clinique\">habituel</span> ou <span class=\"kw-clinique\">inhabituel</span></li>\n        <li><strong>Depuis quand ?</strong> → <span class=\"kw-clinique\">récent</span> ou <span class=\"kw-clinique\">ancien</span></li>\n        <li><strong>En combien de temps la douleur a-t-elle atteint son intensité maximale ?</strong> → <span class=\"kw-clinique\">brutal</span> (&lt;<span class=\"kw-chiffre\"> 1 h</span>, voire « coup de tonnerre » &lt;<span class=\"kw-chiffre\"> 1 min</span>) ou <span class=\"kw-clinique\">progressif</span></li>\n        <li><strong>Que faisiez-vous quand la douleur a débuté ?</strong> (effort, Valsalva, post-coïtal, post-PL…)</li>\n        <li><strong>Symptômes associés ?</strong> (<span class=\"kw-clinique\">fièvre</span>, déficit neuro, <span class=\"kw-clinique\">vomissements</span>, troubles visuels)</li>\n        <li><strong>Contexte particulier ?</strong> (post-partum, <span class=\"kw-etio\">VIH</span>, néoplasie, traumatisme)</li>\n        <li><strong>Caractère positionnel ?</strong> (aggravation debout <span class=\"kw-bio\">vs</span> allongé)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Règle clé d'orientation.</strong> Toute <span class=\"kw-clinique\">céphalée</span> <strong>récente + inhabituelle</strong> est considérée comme <span class=\"kw-etio\">secondaire</span> jusqu'à preuve du contraire (examens en <span class=\"kw-alerte\">urgence</span>). Toute céphalée <strong>ancienne + habituelle</strong> est considérée comme <span class=\"kw-etio\">primaire</span> (prise en charge sans urgence). La <strong>modification d'une céphalée ancienne</strong> doit faire suspecter une céphalée secondaire surajoutée.\n      </div>\n\n      <h4>Interrogatoire face à une <span class=\"kw-clinique\">céphalée</span> chronique — 5 étapes</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Objectif</th><th>Détails à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>1</th><td>Laisser parler le patient</td>\n            <td>Symptômes prédominants ; préoccupations principales</td>\n          </tr>\n          <tr>\n            <th>2</th><td>Caractériser la <span class=\"kw-clinique\">céphalée</span></td>\n            <td><strong>Durée et fréquence</strong> des crises ; <span class=\"kw-clinique\">évolution</span> ; topographie, intensité, type ; facteurs <span class=\"kw-clinique\">aggravants / calmants</span> (alimentaires, hormonaux, émotionnels)</td>\n          </tr>\n          <tr>\n            <th>3</th><td>Signes accompagnateurs</td>\n            <td><strong>Migraineux :</strong> <span class=\"kw-clinique\">nausées</span> ; <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">photo/phonophobie</span> ; pulsatilité<br><strong>Trigémino-autonomiques :</strong> larmoiement ; congestion nasale ; rhinorrhée ; ptosis ; myosis ; rougeur oculaire ; <span class=\"kw-clinique\">œdème</span> palpébral<br><strong>Comportement :</strong> agitation lors des crises<br><strong>Autres :</strong> symptômes focaux ; élément postural</td>\n          </tr>\n          <tr>\n            <th>4</th><td>Restituer le contexte</td>\n            <td>Antécédents ; déclencheurs ; infections ; traumas ; voyages ; situation psychiatrique ; répercussions sommeil/travail/scolarité ; attentes et croyances</td>\n          </tr>\n          <tr>\n            <th>5</th><td>Revoir l'historique thérapeutique</td>\n            <td>Traitements de crise et de fond (durée, dosage, efficacité, EI) ; <strong>fréquence de prise sur les 3 derniers mois</strong> (⚠ exclure un <span class=\"kw-alerte\">abus médicamenteux</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>L'examen clinique face à une <span class=\"kw-clinique\">céphalée</span> comporte au minimum : <span class=\"kw-clinique\">PA</span>, <span class=\"kw-clinique\">température</span> + examen cutané (<span class=\"kw-clinique\">purpura</span>), <span class=\"kw-clinique\">Glasgow</span>, <span class=\"kw-clinique\">raideur méningée</span>, examen <span class=\"kw-clinique\">neurologique focal</span>, <span class=\"kw-clinique\">oculomotricité + pupilles</span>, <span class=\"kw-clinique\">palpation de l'artère temporale</span> (&gt;<span class=\"kw-chiffre\"> 50 ans</span>), examen <span class=\"kw-clinique\">ORL + oculaire</span>, <span class=\"kw-clinique\">fond d'œil</span> (<span class=\"kw-clinique\">œdème</span> papillaire si <span class=\"kw-alerte\">HTIC</span>).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège.</strong> Un examen clinique normal <span class=\"kw-alerte\">n'élimine pas une cause grave</span> et ne doit pas faire retarder les explorations.\n      </div>\n\n      <h4>Distinction <span class=\"kw-clinique\">céphalée</span> <span class=\"kw-bio\">vs</span> algie faciale — rappel anatomique</h4>\n      <p>La <span class=\"kw-def\">céphalée</span> est une douleur de la tête située <strong>au-dessus de la nuque et de la ligne orbito-méatale</strong>. L'<span class=\"kw-def\">algie faciale</span> est située <strong>au-dessous de cette ligne</strong>, en avant du pavillon. La distinction est en pratique floue car toute cause de <span class=\"kw-clinique\">céphalée</span> peut donner une douleur de face et inversement, reflet de l'anatomie du <span class=\"kw-def\">complexe trigémino-cervical</span> qui assure l'innervation nociceptive de l'extrémité céphalique.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/100/anatomie-face-v1-v2-v3.png\"\n             alt=\"Schéma de l'innervation sensitive de la face — territoires V1 (ophtalmique), V2 (maxillaire), V3 (mandibulaire) et plexus cervical superficiel\"\n             loading=\"lazy\">\n        <figcaption>Innervation sensitive de l'extrémité céphalique — territoires du nerf trijumeau (V1/V2/V3), du VIIbis (zone de Ramsay-Hunt) et du plexus cervical superficiel (C1-C3). Source : fiche source EDN item 100.</figcaption>\n      </figure>\n\n      <table >\n        <thead>\n          <tr><th>Nerf</th><th>Type</th><th>Territoire sensitif</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>V1 — ophtalmique</th><td>Exclusivement sensitif</td>\n            <td>Sensibilité <span class=\"kw-clinique\">cornéenne</span> ; hémifront ; paupière supérieure ; racine et dorsum du nez (tout le nez sauf les ailes) ; méninges ; muqueuses nasale, frontale, sphénoïdale</td>\n          </tr>\n          <tr>\n            <th>V2 — maxillaire</th><td>Exclusivement sensitif</td>\n            <td>Aile nasale ; partie haute de la joue ; hémilèvre supérieure ; sensibilités dentaire et muqueuse de l'hémiarcade supérieure ; muqueuses du palais, voile, rhinopharynx, sinus maxillaire</td>\n          </tr>\n          <tr>\n            <th>V3 — mandibulaire</th><td>Mixte (sensitif + moteur)</td>\n            <td>Hémilèvre inférieure ; hémimenton ; partie basse de la joue ; <strong>méat acoustique externe</strong> ; partie supérieure de l'oreille ; hémiarcade dentaire inférieure ; <strong>2/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieurs de la langue</strong> ; plancher buccal</td>\n          </tr>\n          <tr>\n            <th>VIIbis (n. de Wrisberg)</th><td>Sensitif</td>\n            <td><strong>Zone de Ramsay-Hunt</strong> : conque et partie externe du conduit auditif</td>\n          </tr>\n          <tr>\n            <th>Plexus cervical (C1-C3)</th><td>Sensitif</td>\n            <td>Partie basse et postérieure du scalp ; partie postéro-inférieure du pavillon ; conduit auditif externe ; lobule ; région angulo-mandibulaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"muted\"><em>Note : l'innervation sensitive de la face est <strong>tombée en annale</strong> — connaître les territoires V1/V2/V3 et leurs rapports avec la zone de Ramsay-Hunt (utile pour la névralgie du V et le zona).</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/trigeminal-neuralgia","label":"Radiopaedia : Trigeminal neuralgia"},{"href":"https://radiopaedia.org/articles/trigeminal-nerve","label":"Radiopaedia : Trigeminal nerve"},{"href":"https://radiopaedia.org/articles/occipital-neuralgia","label":"Radiopaedia : Occipital neuralgia (Arnold)"},{"href":"https://anatomie-fmpm.uca.ma/wp-content/uploads/2020/08/Innervation-de-la-face-et-du-cou.pdf","label":"FMPM — Innervation face & cou (PDF)"}]},{"id":"100-2","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principales causes de céphalées nécessitant une prise en charge en urgence et leur présentation clinique","contenu":"<p>Toutes les <span class=\"kw-clinique\">céphalées</span> ne se valent pas en termes de <span class=\"kw-alerte\">risque vital</span>. L'orientation du patient se fait sur 3 niveaux : <span class=\"kw-alerte\">urgence</span> vitale immédiate, PEC en urgence (&lt; quelques heures), consultation recommandée.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Urgences vitales.</strong> <span class=\"kw-alerte\">Syndrome méningé</span> (raideur de nuque + <span class=\"kw-clinique\">fièvre</span> = <span class=\"kw-etio\">méningite</span> jusqu'à preuve du contraire ; raideur sans <span class=\"kw-clinique\">fièvre</span> = HSA jusqu'à preuve du contraire). <span class=\"kw-alerte\">Syndrome d'HTIC</span> (<span class=\"kw-clinique\">céphalée</span> progressive + <span class=\"kw-clinique\">vomissements</span> + <span class=\"kw-clinique\">œdème</span> papillaire ± troubles de vigilance).\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Niveau</th><th>Situations cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Urgences vitales</th>\n            <td><strong><span class=\"kw-alerte\">Syndrome méningé</span></strong> ; <strong>syndrome d'<span class=\"kw-alerte\">HTIC</span></strong></td>\n          </tr>\n          <tr>\n            <th>PEC en <span class=\"kw-alerte\">urgence</span></th>\n            <td><strong><span class=\"kw-clinique\">Céphalée</span> brutale</strong> : maximale en <span class=\"kw-chiffre\">&lt; 1 h</span>, voire en « coup de tonnerre » <span class=\"kw-chiffre\">&lt; 1 min</span><br><strong>Céphalée inhabituelle et récente</strong> ou d'aggravation récente <span class=\"kw-chiffre\">&lt; 7 jours</span><br><strong>Céphalée fébrile</strong> (sauf cause générale évidente type syndrome grippal en période épidémique)<br><strong>Céphalée + signes neurologiques</strong> (focaux, <span class=\"kw-clinique\">confusion</span>, crise)<br><strong>Suspicion d'intoxication</strong> (notamment <span class=\"kw-etio\">CO</span> — chauffage défectueux, plusieurs personnes touchées)<br><strong>Céphalée sur immunodépression</strong> (<span class=\"kw-etio\">VIH</span> non contrôlé, transplanté, chimio)</td>\n          </tr>\n          <tr>\n            <th>Consultation recommandée</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> connue ne cédant pas au traitement habituel<br>Céphalée semi-récente (<span class=\"kw-chiffre\">8 jours</span> à<span class=\"kw-chiffre\"> 6 mois</span>) sans signe d'aggravation<br>Céphalée ancienne (<span class=\"kw-chiffre\">≥ 6 mois</span>) dont fréquence/intensité difficiles à gérer</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Principales causes urgentes — présentation clinique</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Présentation typique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-etio\">HSA</span> (anévrismale)</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">explosive</span> en coup de tonnerre ; ± perte de connaissance brève ; ± <span class=\"kw-clinique\">syndrome méningé</span> (raideur de nuque) ; survenue à l'<strong>effort</strong> / <strong>orgasmique</strong> / au <strong>Valsalva</strong> ; représente <span class=\"kw-chiffre\">10-30 %</span> des <span class=\"kw-clinique\">céphalées</span> brutales</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Méningite</span></th>\n            <td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">fébrile</span> ; <span class=\"kw-clinique\">syndrome méningé</span> ; <span class=\"kw-clinique\">purpura</span> fébrile = <strong><span class=\"kw-etio\">méningocoque</span> jusqu'à preuve du contraire</strong> (<span class=\"kw-alerte\">urgence</span> absolue)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">AVC</span> (<span class=\"kw-etio\">ischémique</span> ou <span class=\"kw-etio\">hémorragique</span>)</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">déficit neuro focal</span> brutal ; FDR cardiovasculaire ; <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">hémorragique</span> souvent en « céphalée explosive » ; <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span> de la fosse postérieure peut être explosif</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Dissection</span> artérielle cervicale</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">cervicalgie</span> ipsilatérale ; ± <span class=\"kw-clinique\">syndrome de Claude-Bernard-Horner</span> (carotidienne) ; ± <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span> secondaire ; contexte de <strong>traumatisme rachidien</strong> mineur</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Thrombose veineuse cérébrale</span> (TVC)</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> progressive ou subaiguë ; FDR MTEV (<strong>contraception orale</strong>, post-partum, thrombophilie) ; ± crises comitiales ; ± déficit focal</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Artérite à cellules géantes</span> (Horton)</th>\n            <td>Sujet <span class=\"kw-chiffre\">&gt; 50 ans</span> ; <span class=\"kw-clinique\">céphalée</span> temporale ; <span class=\"kw-clinique\">claudication de la mâchoire</span> ; <span class=\"kw-clinique\">AEG</span> ; ± douleurs des ceintures (PPR) ; artère temporale indurée et sensible<br><strong>Piège :</strong> la <span class=\"kw-alerte\">persistance des douleurs après 4 jours de corticothérapie</span> doit faire reconsidérer le diagnostic</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Intoxication au CO</span></th>\n            <td><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">nausées</span> ; contexte évocateur (<strong>chauffage défectueux</strong>, plusieurs personnes du foyer touchées simultanément, hiver)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">SVCR</span></th>\n            <td><span class=\"kw-clinique\">Céphalées</span> <span class=\"kw-clinique\">ictales récurrentes</span> en coup de tonnerre se répétant sur <span class=\"kw-chiffre\">1-3 semaines</span> ; déclencheurs (effort, Valsalva, substances vasoactives, post-partum) ; représente <span class=\"kw-chiffre\">10-45 %</span> des céphalées brutales</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Apoplexie pituitaire</span></th>\n            <td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">brutale</span> + <span class=\"kw-clinique\">hémianopsie bitemporale</span> (compression chiasma) + <span class=\"kw-clinique\">ophtalmoplégie</span> (atteinte du <span class=\"kw-clinique\">III</span> par compression sinus caverneux) + <span class=\"kw-alerte\">insuffisance antéhypophysaire aiguë</span> (risque d'<span class=\"kw-alerte\">insuffisance surrénale aiguë</span>)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">PRES</span> / <span class=\"kw-etio\">encéphalopathie hypertensive</span></th>\n            <td><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">HTA sévère</span> + <span class=\"kw-clinique\">crises comitiales</span> ± <span class=\"kw-clinique\">troubles visuels</span> (cécité corticale possible) ; contexte : éclampsie, IRC, <span class=\"kw-ttt\">immunosuppresseurs</span>, chimio ; <span class=\"kw-imagerie\">IRM FLAIR</span> = <span class=\"kw-radio\">hypersignaux postérieurs réversibles</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Glaucome aigu</span> par fermeture de l'angle</th>\n            <td><span class=\"kw-clinique\">Œil rouge</span> douloureux unilatéral + <span class=\"kw-clinique\">AV effondrée</span> + <span class=\"kw-clinique\">mydriase aréactive</span> + <span class=\"kw-clinique\">dureté du globe</span> à la palpation + <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span> ; <strong><span class=\"kw-alerte\">urgence</span> ophtalmo</strong> (risque de cécité &lt; quelques heures)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 151 — <span class=\"kw-etio\">Méningite</span> - méningoencéphalite · 340 — <span class=\"kw-etio\">AVC</span> · 195 — <span class=\"kw-etio\">Artérite à cellules géantes</span></em></p>","frequence":2},{"id":"100-3","rang":"A","rubrique":"Étiologies","titre":"Énoncer les principales causes de céphalée aiguë et les caractéristiques cliniques propres à chacune","contenu":"<p>L'orientation étiologique d'une <span class=\"kw-clinique\">céphalée</span> aiguë repose sur 2 axes : (1) le <strong>mode d'installation</strong> (brutal <span class=\"kw-bio\">vs</span> progressif) couplé à la <span class=\"kw-imagerie\">TDM</span> (anormale <span class=\"kw-bio\">vs</span> normale), (2) les <strong>éléments d'orientation</strong> de l'interrogatoire.</p>\n\n      <h4>Causes par mode d'installation et <span class=\"kw-imagerie\">TDM</span></h4>\n      <table >\n        <thead>\n          <tr><th>Mode</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Début brutal<br>+ <span class=\"kw-imagerie\">TDM</span> <strong>anormale</strong></th>\n            <td><span class=\"kw-etio\">Hémorragies intracrâniennes</span> ; <span class=\"kw-etio\">infarctus cérébraux</span> (visibles &gt;<span class=\"kw-chiffre\"> 3 h</span>) ; <span class=\"kw-etio\">tumeurs cérébrales</span> (rare cause de <span class=\"kw-clinique\">céphalée</span> brutale) ; <span class=\"kw-etio\">sinusite aiguë</span> (notamment <strong>sphénoïdale</strong>, diagnostic d'exclusion)</td>\n          </tr>\n          <tr>\n            <th>Début brutal<br>+ <span class=\"kw-imagerie\">TDM</span> <strong>normale</strong></th>\n            <td><span class=\"kw-etio\">HSA</span> ; <span class=\"kw-etio\">SVCR</span> ; <span class=\"kw-etio\">méningite</span> ; <span class=\"kw-etio\">HTIC</span> ; <span class=\"kw-etio\">artérite temporale</span> ; <span class=\"kw-etio\">nécrose pituitaire</span> ; <span class=\"kw-etio\">syndrome d'hypotension intracrânienne</span> ; <span class=\"kw-etio\">AVC ischémique</span> (<span class=\"kw-imagerie\">scanner</span> &lt;<span class=\"kw-chiffre\"> 3 h</span>) ; <span class=\"kw-etio\">dissections artérielles cervicales</span> ; <span class=\"kw-etio\">thromboses veineuses cérébrales</span> ; <span class=\"kw-etio\">encéphalopathie postérieure réversible</span> (PRES) ; <span class=\"kw-etio\">encéphalopathie hypertensive</span></td>\n          </tr>\n          <tr>\n            <th>Début progressif</th>\n            <td><span class=\"kw-etio\">Méningite</span> ; <span class=\"kw-etio\">méningo-encéphalite</span> ; <span class=\"kw-etio\">HTIC</span> ; <span class=\"kw-etio\">artérite temporale</span> ; <span class=\"kw-etio\">intoxication au CO</span> ; <span class=\"kw-etio\">névralgies / neuropathies secondaires</span> ; <span class=\"kw-clinique\">céphalée</span> post-TC aiguë ; affections <strong>ophtalmo / ORL / rhumatologiques</strong> ; <span class=\"kw-etio\">SAS</span> ; <span class=\"kw-etio\">anémie</span> ; <span class=\"kw-etio\">dysthyroïdie</span> ; médicaments (<span class=\"kw-ttt\">IPED</span>, <span class=\"kw-ttt\">dipyridamole</span>, <span class=\"kw-ttt\">dérivés nitrés</span>, <span class=\"kw-ttt\">anticalciques</span> sauf flunarizine)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Orientation étiologique par élément d'interrogatoire</h4>\n      <table >\n        <thead>\n          <tr><th>Élément clinique</th><th>Diagnostic(s) à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr><th>Âge <span class=\"kw-chiffre\">&gt; 50 ans</span> ± douleurs ceintures ± <span class=\"kw-clinique\">AEG</span> ± <span class=\"kw-clinique\">claudication</span> mâchoire</th><td><span class=\"kw-etio\">Artérite temporale</span> (Horton)</td></tr>\n          <tr><th>Aggravation en position <strong>allongée</strong></th><td><span class=\"kw-etio\">HTIC</span></td></tr>\n          <tr><th>Aggravation en position <strong>debout</strong></th><td><span class=\"kw-etio\">Hypotension intracrânienne</span></td></tr>\n          <tr><th>Chauffage défectueux / exposition possible</th><td><span class=\"kw-etio\">Intoxication au CO</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Cervicalgie</span></th><td><span class=\"kw-etio\">Dissection artérielle cervicale</span></td></tr>\n          <tr><th>Début <strong>brutal</strong> (coup de tonnerre)</th><td><span class=\"kw-etio\">HSA</span> ; autres causes vasculaires (<span class=\"kw-etio\">SVCR</span>, <span class=\"kw-etio\">dissection</span>, <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">hémorragique</span>)</td></tr>\n          <tr><th>Début <strong>progressif</strong></th><td><span class=\"kw-etio\">HTIC</span></td></tr>\n          <tr><th>FDR cardiovasculaire</th><td><span class=\"kw-etio\">AVC</span></td></tr>\n          <tr><th>FDR thrombose veineuse (contraception orale, post-partum, thrombophilie)</th><td><span class=\"kw-etio\">Thrombose veineuse cérébrale</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Fièvre</span></th><td>Causes <strong>infectieuses</strong> (<span class=\"kw-etio\">méningite</span> ou infection générale)</td></tr>\n          <tr><th><span class=\"kw-etio\">VIH</span> non contrôlé</th><td><span class=\"kw-etio\">Toxoplasmose cérébrale</span> ; <span class=\"kw-etio\">méningite à cryptocoque</span></td></tr>\n          <tr><th>Néoplasie connue</th><td><span class=\"kw-etio\">Métastase cérébrale</span> ; <span class=\"kw-etio\">méningite carcinomateuse</span></td></tr>\n          <tr><th>Perte de connaissance lors de <span class=\"kw-clinique\">céphalée</span> brutale</th><td><span class=\"kw-etio\">HSA</span></td></tr>\n          <tr><th><span class=\"kw-ttt\">Ponction</span> durale récente / geste à risque</th><td><span class=\"kw-etio\">Hypotension intracrânienne</span></td></tr>\n          <tr><th>Post-partum</th><td><span class=\"kw-etio\">SVCR</span> ; <span class=\"kw-etio\">éclampsie</span> ; <span class=\"kw-etio\">TVC</span> ; <span class=\"kw-clinique\">hypotension</span> intracrânienne (si péridurale)</td></tr>\n          <tr><th>Substances vasoactives (drogues, sérotoninergiques, α-sympathomimétiques)</th><td><span class=\"kw-etio\">SVCR</span></td></tr>\n          <tr><th>Survenue brutale à l'<strong>effort</strong> ou orgasmique</th><td><span class=\"kw-etio\">HSA</span> ; <span class=\"kw-etio\">SVCR</span></td></tr>\n          <tr><th>Survenue lors d'un Valsalva (<span class=\"kw-clinique\">toux</span>, défécation)</th><td><span class=\"kw-etio\">SVCR</span> ; <span class=\"kw-etio\">HTIC</span></td></tr>\n          <tr><th>Traumatisme crânien récent</th><td><span class=\"kw-etio\">Hémorragie cérébrale</span> ; <span class=\"kw-etio\">hématome sous-dural</span></td></tr>\n          <tr><th>Traumatisme rachidien</th><td><span class=\"kw-etio\">Dissection artérielle cervicale</span> ; <span class=\"kw-clinique\">hypotension</span> intracrânienne</td></tr>\n          <tr><th><span class=\"kw-clinique\">Vomissements</span></th><td><span class=\"kw-etio\">HTIC</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Hémianopsie bitemporale</span></th><td><span class=\"kw-etio\">Apoplexie pituitaire</span> (compression du chiasma optique)</td></tr>\n          <tr><th>Atteinte du <span class=\"kw-clinique\">III</span> (mydriase + ptosis)</th><td><span class=\"kw-etio\">Anévrisme de l'a. carotide interne supra-clinoïdienne</span> ; <span class=\"kw-etio\">apoplexie pituitaire</span> (sinus caverneux)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Focus 1 — <span class=\"kw-clinique\">Syndrome de vasoconstriction</span> cérébrale réversible (SVCR)</h4>\n      <p>Le SVCR représente <span class=\"kw-chiffre\">10 à 45 %</span> des <span class=\"kw-clinique\">céphalées</span> brutales. Vasoconstriction des artères cérébrales <strong>réversible en <span class=\"kw-chiffre\">3 mois</span></strong>, qui peut se compliquer d'<span class=\"kw-alerte\">infarctus cérébraux</span> ou d'<span class=\"kw-alerte\">hémorragie</span> (HSA, hémorragie cérébrale).</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Circonstances</th>\n            <td>Présentes dans <span class=\"kw-chiffre\">50 %</span> des cas : <strong>post-partum</strong> ; stress ; substances vasoactives (<span class=\"kw-ttt\">antidépresseurs sérotoninergiques</span> ; <span class=\"kw-ttt\">triptans</span> ; <span class=\"kw-ttt\">décongestionnants</span> si rhume ; <span class=\"kw-ttt\">cannabis</span>)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Céphalée</span></th>\n            <td><strong>Installation :</strong> explosive, en coup de tonnerre<br><strong>Durée :</strong><span class=\"kw-chiffre\"> 5 min</span> à plusieurs heures, se répètent pendant <span class=\"kw-chiffre\">1 à 3 semaines</span><br><strong>Déclencheurs :</strong> effort ; émotion ; activité sexuelle ; Valsalva (<span class=\"kw-clinique\">toux</span>, défécation)<br><strong>Associé :</strong> poussée hypertensive ; crises comitiales ; déficits focaux</td>\n          </tr>\n          <tr>\n            <th>Paraclinique</th>\n            <td><strong>Imagerie parenchyme</strong> (<span class=\"kw-imagerie\">IRM</span>/<span class=\"kw-imagerie\">TDM</span>) : normale sauf complications<br><strong><span class=\"kw-imagerie\">Angiographie</span></strong> (<span class=\"kw-imagerie\">Angio-IRM</span>/<span class=\"kw-imagerie\">TDM</span>/cathétérisme) : <span class=\"kw-radio\">sténoses artérielles segmentaires et diffuses</span> ; <span class=\"kw-alerte\">peut être normale &lt; 7 j</span>, sténoses maximales à <span class=\"kw-chiffre\">2 semaines</span> → justifie de refaire l'<span class=\"kw-imagerie\">angiographie</span> quelques jours plus tard si la 1ʳᵉ est normale</td>\n          </tr>\n          <tr>\n            <th>Arguments diagnostiques</th>\n            <td>Facteur déclenchant + <span class=\"kw-clinique\">céphalées</span> ictales récurrentes + vasospasmes en imagerie. <strong>HSA sans anévrisme identifié peut être un SVCR.</strong></td>\n          </tr>\n          <tr>\n            <th>Traitement</th>\n            <td>Repos ; arrêt des substances vasoactives ; <span class=\"kw-ttt\">nimodipine</span> (anticalcique)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus 2 — Syndrome d'<span class=\"kw-clinique\">hypotension</span> intracrânienne</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Contexte</th>\n            <td>Soit quelques heures <strong>après un geste</strong> = péridurale &gt; <span class=\"kw-bio\">ponction lombaire</span>, rachianesthésie ; soit <strong>brèche spontanée</strong> ou provoquée par un traumatisme rachidien mineur</td>\n          </tr>\n          <tr>\n            <th>Clinique</th>\n            <td><strong><span class=\"kw-clinique\">Céphalée</span> orthostatique</strong> en position debout ou assise : disparaît <span class=\"kw-chiffre\">en 15 min</span> en décubitus ; début progressif (<span class=\"kw-chiffre\">85 %</span>) ou brutal (<span class=\"kw-chiffre\">15 %</span>)<br><strong>Associé :</strong> cervicalgie ; vision floue ; acouphènes non pulsatiles ; baisse acuité auditive ; <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span><br><strong>Inconstant :</strong> diplopie horizontale par atteinte du <span class=\"kw-clinique\">VI</span></td>\n          </tr>\n          <tr>\n            <th>Imagerie</th>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> cérébrale :</strong> normale<br><strong><span class=\"kw-imagerie\">IRM</span></strong> (non nécessaire dans les formes typiques post-PL) : <span class=\"kw-radio\">rehaussement diffus et régulier des méninges</span> (pachyméninge) après gadolinium ; <span class=\"kw-radio\">déplacement crânio-caudal des structures encéphaliques</span> (ptose amygdalienne cérébelleuse) ; aspect collabé des ventricules</td>\n          </tr>\n          <tr>\n            <th>Risques</th>\n            <td>Si non traitée : <span class=\"kw-alerte\">hématomes sous-duraux bilatéraux</span> ; <span class=\"kw-alerte\">thrombose veineuse cérébrale</span> — à suspecter si <strong>disparition du caractère orthostatique</strong> avec <span class=\"kw-clinique\">céphalée</span> permanente, ou apparition d'un signe neurologique</td>\n          </tr>\n          <tr>\n            <th>PEC</th>\n            <td><span class=\"kw-ttt\">Blood patch épidural</span> (injection de sang autologue dans l'espace épidural) peut être nécessaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 151 — <span class=\"kw-etio\">Méningite</span> - méningoencéphalite · 340 — <span class=\"kw-etio\">AVC</span></em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/spontaneous-intracranial-hypotension-2","label":"Radiopaedia : Spontaneous intracranial hypotension"}]},{"id":"100-4","rang":"B","rubrique":"Étiologies","titre":"Énoncer les principales causes de céphalée chronique (épisodique ou quotidienne) et les caractéristiques cliniques propres à chacune","contenu":"<p>Le terme « chronique » dans la <span class=\"kw-def\">classification</span> des <span class=\"kw-clinique\">céphalées</span> a <strong>3 significations distinctes</strong> qu'il faut maîtriser pour ne pas mélanger les seuils diagnostiques.</p>\n\n      <table >\n        <thead>\n          <tr><th>Sens du mot « chronique »</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>« Dure depuis &gt;<span class=\"kw-chiffre\"> 3 mois</span> »</th>\n            <td><span class=\"kw-clinique\">Céphalées</span> primaires (années) ; certaines céphalées secondaires persistant &gt;<span class=\"kw-chiffre\"> 3 mois</span> (<span class=\"kw-clinique\">céphalée</span> post-traumatique)</td>\n          </tr>\n          <tr>\n            <th>« Survient <span class=\"kw-chiffre\">≥ 15</span> j / mois » (CCQ)</th>\n            <td><span class=\"kw-def\">Céphalée chronique quotidienne</span> avec crises de longue durée (&gt;<span class=\"kw-chiffre\"> 4 h</span>) : <span class=\"kw-def\">migraine</span> chronique surtout, <span class=\"kw-clinique\">céphalée</span> de tension chronique plus rarement</td>\n          </tr>\n          <tr>\n            <th>« AVF chronique » (rémission &gt;<span class=\"kw-chiffre\"> 1 an</span>)</th>\n            <td>Algie vasculaire de la face <strong>chronique</strong> (par opposition à l'AVF épisodique avec rémissions &gt;<span class=\"kw-chiffre\"> 3 mois</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Classification</span> des <span class=\"kw-clinique\">céphalées</span> chroniques</h4>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Évolution</span></th><th>Définition</th><th>Principales causes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Paroxystique (épisodique)</th>\n            <td><span class=\"kw-chiffre\">&lt; 15 j / mois</span></td>\n            <td>Basse fréquence &lt; 8 j/mois ou haute fréquence 8-14 j/mois<br><strong>Causes :</strong> <span class=\"kw-def\">migraine</span> épisodique ; <span class=\"kw-clinique\">céphalée</span> de tension épisodique</td>\n          </tr>\n          <tr>\n            <th>Continue (CCQ)</th>\n            <td><span class=\"kw-chiffre\">≥ 15 j / mois depuis ≥ 3 mois</span></td>\n            <td><strong>Imagerie cérébrale systématique <span class=\"kw-chiffre\">≥ 1</span> fois</strong><br><strong>Courte durée (&lt;<span class=\"kw-chiffre\"> 4 h</span>) :</strong> AVF ; névralgie du V<br><strong>Longue durée (&gt;<span class=\"kw-chiffre\"> 4 h</span>) :</strong> contexte d'<span class=\"kw-alerte\">abus médicamenteux dans 80 %</span> ; <span class=\"kw-def\">migraine</span> chronique (++) ; <span class=\"kw-clinique\">céphalée</span> de tension chronique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus 1 — <span class=\"kw-clinique\">Céphalée</span> de tension</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Fréquence</th>\n            <td><strong>Épisodique (&lt; 15 j/mois) :</strong> <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">30-80 %</span> (souvent associée à la <span class=\"kw-def\">migraine</span>)<br><strong>Chronique (<span class=\"kw-chiffre\">≥ 15</span> j/mois) :</strong> <span class=\"kw-chiffre\">1-2 %</span> des adultes</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Terrain</span></th>\n            <td>Débute souvent à l'<strong>adolescence</strong> ; prédominance féminine <span class=\"kw-chiffre\">3F/2H</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Physiopathologie</span></th>\n            <td><strong>Aucun rapport avec l'<span class=\"kw-def\">HTA</span>.</strong> Douleur dysfonctionnelle par interaction : facteurs neurologiques centraux (dysfonction du contrôle de la douleur) + facteurs périphériques myogènes (crispation des muscles péricrâniens)<br><strong>Déclencheurs physiques :</strong> mauvaise posture tête/cou ; <span class=\"kw-etio\">sédentarité</span> ; posture de travail<br><strong>Déclencheurs psychologiques :</strong> stress ; contrariété ; surmenage</td>\n          </tr>\n          <tr>\n            <th>Critères ICHD-3</th>\n            <td><strong>A :</strong> <span class=\"kw-chiffre\">≥ 10</span> épisodes répondant aux critères B-D<br><strong>B :</strong> durée <span class=\"kw-chiffre\">30 min à 7 jours</span><br><strong>C :</strong> <span class=\"kw-chiffre\">≥ 2</span> des caractéristiques : bilatérale (antérieures « en barre » ou postérieures avec cervicalgies) ; <span class=\"kw-clinique\">pression ou serrement « étau »</span> non pulsatile ; intensité faible à modérée ; <span class=\"kw-clinique\">absence d'aggravation</span> par l'activité physique<br><strong>D :</strong> absence de <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span> ; photo OU phono mais pas les 2 (≠ <span class=\"kw-def\">migraine</span>)<br><strong>E :</strong> n'est pas mieux expliqué par un autre diagnostic ICHD-3</td>\n          </tr>\n          <tr>\n            <th>Calmant</th>\n            <td>Peut être <strong>améliorée par l'activité physique</strong> ; s'améliore quand le sujet est détendu ou occupé</td>\n          </tr>\n          <tr>\n            <th>Paraclinique</th>\n            <td><strong>Aucun examen sauf doute diagnostique</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus 2 — <span class=\"kw-clinique\">Céphalée</span> chronique quotidienne (CCQ)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Définition</th>\n            <td><span class=\"kw-chiffre\">≥ 15 j/mois depuis &gt; 3 mois</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Prévalence</span></th>\n            <td><span class=\"kw-chiffre\">3 %</span> (<span class=\"kw-def\">migraine</span> chronique <span class=\"kw-chiffre\">1,7 %</span> + <span class=\"kw-clinique\">céphalée</span> de tension chronique <span class=\"kw-chiffre\">1-2 %</span>)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Terrain</span></th>\n            <td>Prédominance féminine, <strong><span class=\"kw-chiffre\">40-50 ans</span></strong> ; généralement patients atteints de <span class=\"kw-def\">migraine</span> ou plus rarement de <span class=\"kw-def\">céphalée de tension</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Physiopathologie</span></th>\n            <td>Complication de la <span class=\"kw-def\">migraine</span> et/ou de la <span class=\"kw-clinique\">céphalée</span> de tension épisodique en <strong>4 étapes</strong> :<br>1. Crises de plus en plus fréquentes<br>2. Recours aux traitements de plus en plus souvent (<span class=\"kw-alerte\">abus médicamenteux</span> associé dans <span class=\"kw-chiffre\">80 %</span>)<br>3. Traitements de moins en moins efficaces (<span class=\"kw-alerte\">accoutumance</span>)<br>4. <span class=\"kw-clinique\">Céphalées</span> permanentes apparaissent</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Comorbidités</span></th>\n            <td><span class=\"kw-def\">Comorbidité</span> psychiatrique élevée (<span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">dépression</span>) qui réduit les systèmes de contrôle de la douleur</td>\n          </tr>\n          <tr>\n            <th>Démarche diagnostique</th>\n            <td>Exclure une cause secondaire : <span class=\"kw-imagerie\">IRM cérébrale</span> (<span class=\"kw-imagerie\">TDM</span> à défaut) ; exclure une CCQ de courte durée (&lt;<span class=\"kw-chiffre\"> 4 h</span>) = AVF, névralgie ; <strong>rechercher systématiquement un abus <span class=\"kw-etio\">médicamenteux</span> (<span class=\"kw-chiffre\">80 %</span>)</strong> présent depuis &gt;<span class=\"kw-chiffre\"> 3 mois</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Critères ICHD-3 de la <span class=\"kw-clinique\">céphalée</span> par abus <span class=\"kw-etio\">médicamenteux</span></h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>A</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> survenant <span class=\"kw-chiffre\">≥ 15 j/mois</span> chez un patient ayant une céphalée préexistante</td>\n          </tr>\n          <tr>\n            <th>B</th>\n            <td>Surconsommation régulière depuis <span class=\"kw-chiffre\">&gt; 3 mois</span> :<br>1. <span class=\"kw-ttt\">Antalgiques non opioïdes</span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">paracétamol</span>) pris <span class=\"kw-chiffre\">≥ 15 j/mois</span><br>2. <span class=\"kw-ttt\">Triptans</span>, <span class=\"kw-ttt\">ergotamine</span>, <span class=\"kw-ttt\">opiacés</span> et/ou <span class=\"kw-ttt\">antalgiques combinés</span> pris <span class=\"kw-chiffre\">≥ 10 j/mois</span></td>\n          </tr>\n          <tr>\n            <th>C</th>\n            <td>N'est pas mieux expliqué par un autre diagnostic ICHD-3</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Attention.</strong> Les <span class=\"kw-ttt\">antalgiques</span> consommés pour une <strong>autre indication</strong> (lombalgie, douleur chronique…) sont pris en compte dans le décompte. C'est souvent le piège chez le patient migraineux par ailleurs traité pour autre chose.\n      </div>\n\n      <h4>Comparatif des principales <span class=\"kw-clinique\">céphalées</span> primaires épisodiques</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Tension épisodique</th><th><span class=\"kw-def\">Migraine</span></th><th>AVF</th><th>Névralgie V</th></tr>\n        </thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Prévalence</span></th><td><span class=\"kw-chiffre\">50-70 %</span></td><td><span class=\"kw-chiffre\">12 %</span></td><td>1/1000</td><td>5/100 000/an</td></tr>\n          <tr><th>Sex-ratio</th><td>3F/2H</td><td>2F/1H</td><td><strong>4-5H/1F</strong></td><td>F</td></tr>\n          <tr><th>Âge</th><td>Adolescence</td><td>Puberté, pic <span class=\"kw-chiffre\">35-40 ans</span></td><td>Adulte jeune <span class=\"kw-chiffre\">30 ans</span></td><td>F &gt;<span class=\"kw-chiffre\"> 50 ans</span></td></tr>\n          <tr><th>Durée</th><td><span class=\"kw-chiffre\">30 min</span> - 7 j</td><td><span class=\"kw-chiffre\">4-72 h</span></td><td><span class=\"kw-chiffre\">15-180 min</span></td><td>&lt;<span class=\"kw-chiffre\"> 2 min</span></td></tr>\n          <tr><th>Intensité</th><td>Légère-modérée</td><td>Modérée-sévère</td><td>Sévère-très sévère</td><td>Sévère-très sévère</td></tr>\n          <tr><th>Latéralité</th><td>Bilatérale</td><td>Unilatérale</td><td>Strictement unilatérale (même côté)</td><td>Strictement unilatérale (même côté)</td></tr>\n          <tr><th>Type</th><td>Pression / serrement</td><td>Pulsatile</td><td>Intolérable, atroce</td><td>Décharge, élancement</td></tr>\n          <tr><th>Effet activité physique</th><td>Non aggravée, parfois améliorée</td><td><strong>Aggravée</strong>, attitude calme</td><td>Non aggravée, agitation</td><td>Aggravée par parole, mastication</td></tr>\n          <tr><th>Dysautonomie</th><td>Jamais</td><td>Possible</td><td><strong>Importante</strong> (larmoiement, myosis…)</td><td>Absente</td></tr>\n          <tr><th>Signes associés</th><td>Photo ou phono (pas les 2)</td><td>Phono + photo + <span class=\"kw-clinique\">nausées</span></td><td>Déclenché par <strong><span class=\"kw-etio\">alcool</span></strong> ; périodicité circadienne</td><td>Zone gâchette V2/V3</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":1},{"id":"100-5","rang":"A","rubrique":"Étiologies","titre":"Énoncer les principales causes des céphalées récentes d’aggravation progressive et les caractéristiques cliniques propres à chacune","contenu":"<p>Une <span class=\"kw-clinique\">céphalée</span> <strong>récente</strong> (&lt;<span class=\"kw-chiffre\"> 7 jours</span>) et <strong>d'aggravation progressive</strong> doit faire suspecter en priorité un <span class=\"kw-alerte\">processus expansif intracrânien</span> ou une <span class=\"kw-alerte\">cause vasculaire</span> (<span class=\"kw-etio\">dissection</span>, thrombose veineuse cérébrale). Imagerie cérébrale rapidement (cf obj-7).</p>\n\n      <h4>Causes principales par mécanisme</h4>\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Étiologies</th><th>Présentation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Processus expansif intracrânien</th>\n            <td><span class=\"kw-etio\">Tumeur cérébrale</span> primitive ou secondaire ; <span class=\"kw-etio\">abcès cérébral</span> ; <span class=\"kw-etio\">méningite carcinomateuse</span></td>\n            <td><span class=\"kw-clinique\">Céphalée</span> matinale, <span class=\"kw-clinique\">vomissements en jet</span>, aggravation à la <span class=\"kw-clinique\">toux/effort/Valsalva</span> ; ± <span class=\"kw-clinique\">œdème papillaire</span> au <span class=\"kw-imagerie\">FO</span> ; ± déficit focal ; ± crises comitiales</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">HTIC</span></th>\n            <td><span class=\"kw-etio\">HTIC tumorale</span> ; <span class=\"kw-etio\">HTIC idiopathique</span> (femme jeune, obèse) ; <span class=\"kw-etio\">TVC</span></td>\n            <td><span class=\"kw-clinique\">Céphalée</span> diffuse, aggravée en <strong>position allongée</strong> et le matin ; éclipses visuelles ; diplopie par atteinte du <span class=\"kw-clinique\">VI</span> ; <span class=\"kw-clinique\">œdème</span> papillaire</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Inflammatoire</span> / vasculaire</th>\n            <td><span class=\"kw-etio\">Artérite à cellules géantes</span> (Horton, sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span>)</td>\n            <td><span class=\"kw-clinique\">Céphalée</span> temporale ; <span class=\"kw-clinique\">claudication de la mâchoire</span> ; <span class=\"kw-clinique\">AEG</span> ; ± PPR ; <strong>artère temporale indurée + sensible</strong> à la palpation ; <span class=\"kw-bio\">VS</span> / <span class=\"kw-bio\">CRP</span> très élevées</td>\n          </tr>\n          <tr>\n            <th>Méningé</th>\n            <td><span class=\"kw-etio\">Méningite</span> ; <span class=\"kw-etio\">méningo-encéphalite</span></td>\n            <td><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">syndrome méningé</span> ; ± troubles vigilance ; ± <span class=\"kw-clinique\">purpura</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Toxique</span></th>\n            <td><span class=\"kw-etio\">Intoxication au CO</span> ; <span class=\"kw-etio\">médicaments</span> (<span class=\"kw-ttt\">IPED</span>, <span class=\"kw-ttt\">dipyridamole</span>, <span class=\"kw-ttt\">dérivés nitrés</span>, <span class=\"kw-ttt\">anticalciques</span> sauf flunarizine)</td>\n            <td>CO : contexte évocateur (chauffage défectueux, foyer touché), <span class=\"kw-clinique\">nausées</span>, troubles conscience<br>Médicaments : <span class=\"kw-clinique\">céphalée</span> s'installant avec l'introduction du médicament, réversible à l'arrêt</td>\n          </tr>\n          <tr>\n            <th>Locorégional</th>\n            <td>Affections <span class=\"kw-etio\">ORL</span> (sinusite chronique, otite), <span class=\"kw-etio\">ophtalmo</span> (glaucome, troubles réfraction), <span class=\"kw-etio\">stomatologique</span>, <span class=\"kw-etio\">rhumatologique</span> cervicale</td>\n            <td>Sinusite : <span class=\"kw-clinique\">céphalée</span> frontale, fébrile, rhinorrhée ; glaucome aigu : œil rouge douloureux, mydriase aréactive ; cervicale : douleur projetée à la nuque/occiput, contractures paravertébrales</td>\n          </tr>\n          <tr>\n            <th>Métabolique / systémique</th>\n            <td><span class=\"kw-etio\">SAS</span> ; <span class=\"kw-etio\">anémie</span> ; <span class=\"kw-etio\">dysthyroïdie</span></td>\n            <td>SAS : <span class=\"kw-clinique\">céphalée</span> matinale, somnolence diurne, ronflements ; anémie : <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">pâleur</span> ; dysthyroïdie : signes hyper/hypothyroïdiens associés</td>\n          </tr>\n          <tr>\n            <th>Post-traumatique</th>\n            <td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-etio\">post-TC aiguë</span></td>\n            <td>Apparaît par définition <span class=\"kw-chiffre\">&lt; 7 jours</span> après TC ; doit faire <strong>exclure une cause secondaire plus grave</strong> (<span class=\"kw-alerte\">dissection</span>, <span class=\"kw-alerte\">hématome sous-dural</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Cas particulier — affections rhumatologiques chroniques</h4>\n      <p>Trop souvent <strong>incriminées à tort</strong> chez des patients ayant une <span class=\"kw-def\">migraine</span>, mais certaines affections rhumatologiques peuvent donner des <span class=\"kw-clinique\">céphalées</span> secondaires d'origine cervicale : <span class=\"kw-etio\">arthrose sévère</span> et/ou conflit disco-radiculaire ; séquelles de fracture/luxation d'une vertèbre cervicale ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span>. Les céphalées sont alors généralement <strong>postérieures</strong> avec des <span class=\"kw-clinique\">contractures musculaires paravertébrales</span> associées.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> à ne pas rater.</strong> Une <span class=\"kw-clinique\">céphalée</span> <strong>récente + progressive</strong> chez un sujet âgé &gt;<span class=\"kw-chiffre\"> 50 ans</span> impose <span class=\"kw-imagerie\">VS + CRP</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">Horton</span>) en plus de l'imagerie cérébrale — risque de <span class=\"kw-alerte\">cécité par NOIAA</span> en l'absence de <span class=\"kw-ttt\">corticothérapie</span> rapide.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 195 — <span class=\"kw-etio\">Artérite à cellules géantes</span> · 151 — <span class=\"kw-etio\">Méningite</span> - méningoencéphalite · 340 — <span class=\"kw-etio\">AVC</span> · 110 — Trouble du sommeil (SAS) · 213 — <span class=\"kw-etio\">Anémie</span></em></p>","frequence":1},{"id":"100-6","rang":"A","rubrique":"Identifier une urgence","titre":"Discuter l’indication d’une hospitalisation et d’une ponction lombaire devant une céphalée aiguë en connaissant la pertinence de cet examen","contenu":"<h4>Indications d'<span class=\"kw-alerte\">hospitalisation</span></h4>\n      <ul>\n        <li>Diagnostic de <span class=\"kw-alerte\">céphalée secondaire grave</span> établi → poursuite du bilan et traitement étiologique</li>\n        <li>Diagnostic non établi <strong>et <span class=\"kw-clinique\">céphalée</span> intense persistante</strong> → poursuivre les explorations et adapter le traitement</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Bon à savoir.</strong> Les explorations s'avèrent <span class=\"kw-chiffre\">normales chez 30 à 70 %</span> des patients explorés pour une <span class=\"kw-clinique\">céphalée</span> récente inhabituelle. Si le patient est soulagé → <strong>RAD possible</strong>. Si c'est un 1ᵉʳ épisode → aucun <span class=\"kw-def\">diagnostic étiologique</span> précis n'est possible (recul temporel et plusieurs crises sont indispensables pour diagnostiquer une céphalée primaire).\n      </div>\n\n      <h4>Indications de la <span class=\"kw-bio\">ponction lombaire</span> (PL)</h4>\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Modalités / Pertinence</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Suspicion d'<span class=\"kw-etio\">HSA</span> avec imagerie normale</th>\n            <td><strong>Pas avant <span class=\"kw-chiffre\">6 h</span></strong> (le temps que la xanthochromie apparaisse) ; fenêtre utile <span class=\"kw-chiffre\">entre 12 h et 14 jours</span> ; recherche de <span class=\"kw-bio\">xanthochromie</span> + GR</td>\n          </tr>\n          <tr>\n            <th>Suspicion de <span class=\"kw-etio\">méningite infectieuse</span></th>\n            <td>PL en <span class=\"kw-alerte\">urgence</span> pour analyse cytobactériologique du <span class=\"kw-bio\">LCS</span> ; toujours après <span class=\"kw-imagerie\">TDM</span> si signes de focalisation, trouble vigilance, immunodépression, ATCD neuro</td>\n          </tr>\n          <tr>\n            <th>Suspicion d'<span class=\"kw-etio\">HTIC</span> avec imagerie non diagnostique</th>\n            <td><strong>Mesure de la pression du <span class=\"kw-bio\">LCS</span> en décubitus latéral gauche</strong> + <span class=\"kw-imagerie\">fond d'œil</span> ; <span class=\"kw-alerte\">HTIC</span> si pression <span class=\"kw-chiffre\">&gt; 25 cm H₂O</span> en l'absence de cause organique</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Céphalée</span> aiguë après imagerie sans diagnostic certain</th>\n            <td>PL pour éliminer les causes méningées (HSA tardive, <span class=\"kw-etio\">méningite</span> peu symptomatique)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pertinence de la PL pour HSA.</strong> La sensibilité de la <span class=\"kw-imagerie\">TDM</span> cérébrale sans injection pour l'HSA est très bonne dans les premières heures (~<span class=\"kw-chiffre\"> 100 %</span> à<span class=\"kw-chiffre\"> 6 h</span>) mais <strong>chute avec le temps</strong> (~<span class=\"kw-chiffre\"> 80 %</span> à<span class=\"kw-chiffre\"> 24 h</span>, ~<span class=\"kw-chiffre\"> 50 %</span> à<span class=\"kw-chiffre\"> 1 semaine</span>). La PL conserve donc tout son intérêt face à une <span class=\"kw-clinique\">céphalée</span> brutale avec <span class=\"kw-imagerie\">TDM</span> normale, surtout si elle est différée — fenêtre <span class=\"kw-chiffre\">12 h</span> à<span class=\"kw-chiffre\"> 14 jours</span> pour la xanthochromie.\n      </div>\n\n      <h4><span class=\"kw-ci\">Contre-indications</span> de la <span class=\"kw-bio\">ponction lombaire</span></h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Situations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-ci\">TDM avant PL obligatoire</span><br>(risque d'engagement)</th>\n            <td><span class=\"kw-clinique\">Signes de focalisation</span> neurologique ; <span class=\"kw-clinique\">troubles de la vigilance</span> (Glasgow &lt; 15) ; <span class=\"kw-clinique\">crises comitiales</span> récentes ; <span class=\"kw-clinique\">immunodépression</span> (<span class=\"kw-etio\">VIH</span> non contrôlé, transplanté, chimio) ; ATCD de pathologie neurologique focale</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-ci\">CI absolues</span></th>\n            <td><span class=\"kw-alerte\">HTIC sur processus expansif</span> (<span class=\"kw-clinique\">lésion</span> focale, hydrocéphalie non communicante) → engagement cérébral ; <span class=\"kw-alerte\">troubles de l'hémostase</span> (<span class=\"kw-bio\">TP</span> &lt;<span class=\"kw-chiffre\"> 50 %</span>, <span class=\"kw-bio\">plaquettes</span> &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> G/L</span>, <span class=\"kw-ttt\">anticoagulation</span> curative non interrompue) ; <span class=\"kw-alerte\">infection cutanée</span> du site de <span class=\"kw-ttt\">ponction</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-ci\">CI relatives</span></th>\n            <td>Instabilité hémodynamique/respiratoire ; refus du patient ; déformation rachidienne majeure</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 151 — <span class=\"kw-etio\">Méningite</span> - méningoencéphalite</em></p>","frequence":0},{"id":"100-7","rang":"A","rubrique":"Prise en charge","titre":"Savoir mettre en route un traitement des céphalées aux urgences","contenu":"<p>La prise en charge aux urgences distingue 2 situations : (1) <span class=\"kw-clinique\">céphalée</span> <strong>récente + inhabituelle</strong> où le traitement est avant tout <span class=\"kw-def\">étiologique</span> ; (2) crise de céphalée <strong>primaire</strong> connue où le traitement est <span class=\"kw-def\">symptomatique</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Traitement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Céphalée récente + inhabituelle</th>\n            <td><strong>Traitement étiologique ++</strong> (selon la cause identifiée)<br><strong>Antalgie en IV</strong> si troubles digestifs : <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-ttt\">néfopam</span><br><strong>Mais éviter <span class=\"kw-ci\">AINS</span> / <span class=\"kw-ci\">aspirine</span></strong> tant que le diagnostic n'est pas posé (risque d'aggravation d'une HSA ou d'un <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">hémorragique</span>)<br><strong>Antiémétique :</strong> <span class=\"kw-ttt\">métoclopramide</span></td>\n          </tr>\n          <tr>\n            <th>Crise de <span class=\"kw-clinique\">céphalée</span> primaire</th>\n            <td><strong>Isoler le patient au calme</strong> (chambre sombre, silencieuse)<br><strong>Réhydratation</strong> si nécessaire<br><strong>Antalgie en IV :</strong> <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-ttt\">néfopam</span> ; <span class=\"kw-ttt\">kétoprofène</span> (<span class=\"kw-ttt\">AINS</span> autorisé une fois le diagnostic primaire posé)<br><strong>Antiémétique :</strong> <span class=\"kw-ttt\">métoclopramide</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Règle de prudence.</strong> Tant que la cause d'une <span class=\"kw-clinique\">céphalée</span> récente inhabituelle n'est pas formellement écartée, on s'abstient des <span class=\"kw-ci\">AINS</span> et de l'<span class=\"kw-ci\">aspirine</span> — ils peuvent aggraver un saignement intracrânien (HSA, <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">hémorragique</span>, hématome sous-dural). <span class=\"kw-ttt\">Paracétamol</span> + <span class=\"kw-ttt\">néfopam</span> IV en attendant.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":0},{"id":"100-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication et la pertinence de l’imagerie devant une céphalée aiguë et chronique chez l’adulte et l’enfant","contenu":"<p>L'imagerie est le pilier de l'exploration des <span class=\"kw-clinique\">céphalées</span> récentes et inhabituelles. La stratégie dépend de 2 critères : (1) <strong>mode d'installation</strong> (brutal <span class=\"kw-bio\">vs</span> progressif), (2) <strong>contexte chronique</strong> ou aigu.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Les 3 dogmes d'exploration.</strong> Toute <span class=\"kw-clinique\">céphalée</span> <span class=\"kw-alerte\">brutale</span> est explorée comme une <span class=\"kw-etio\">HSA anévrismale</span>. Toute céphalée <span class=\"kw-alerte\">progressive</span> est explorée comme une <span class=\"kw-etio\">HTIC</span>. Toute céphalée <span class=\"kw-alerte\">fébrile</span> est explorée comme une <span class=\"kw-etio\">méningite</span>.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 472\" role=\"img\" aria-label=\"Arbre décisionnel de l'indication de l'imagerie devant une céphalée. Première question discriminante : la céphalée est-elle récente, inhabituelle ou d'aggravation récente avec un drapeau rouge ? Si non, c'est une céphalée ancienne et habituelle, donc une céphalée primaire qui ne nécessite pas d'imagerie en urgence ; une IRM cérébrale est réalisée au moins une fois, sans urgence, seulement si le tableau ne correspond pas à une migraine sans aura typique selon l'ICHD-3. Si oui, la céphalée est suspecte d'être secondaire et la deuxième question discriminante est le mode d'installation. Si l'installation est brutale en coup de tonnerre, on réalise en urgence une TDM cérébrale sans injection à la recherche d'une hémorragie sous-arachnoïdienne, complétée par une angio-TDM ; troisième question discriminante : si cette imagerie est normale, on réalise une ponction lombaire à la recherche de xanthochromie, et on répète l'angiographie quelques jours plus tard en cas de suspicion de syndrome de vasoconstriction cérébrale réversible. Si l'installation est progressive, on réalise d'emblée une IRM cérébrale complète à la recherche d'un processus expansif intracrânien ou d'une cause vasculaire comme une thrombose veineuse cérébrale ou une dissection.\" style=\"height:auto;display:block;border-radius:8px\">\n          <!-- Q1 : drapeau rouge / céphalée secondaire -->\n          <rect class=\"fb-blue\" x=\"96\" y=\"10\" width=\"368\" height=\"50\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"31\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Céphalée récente, inhabituelle ou aggravée ?</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"48\" text-anchor=\"middle\" font-size=\"11\">(<span class=\"kw-alerte\">drapeau rouge</span> = suspicion de cause secondaire)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"60\" x2=\"280\" y2=\"74\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"120\" y1=\"74\" x2=\"440\" y2=\"74\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"120\" y1=\"74\" x2=\"120\" y2=\"90\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"120,96 115,88 125,88\"/>\n          <line class=\"ln\" x1=\"440\" y1=\"74\" x2=\"440\" y2=\"90\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"440,96 435,88 445,88\"/>\n          <text class=\"tx-muted\" x=\"100\" y=\"86\" text-anchor=\"end\" font-size=\"10.5\" font-weight=\"600\">NON</text>\n          <text class=\"tx-muted\" x=\"460\" y=\"86\" text-anchor=\"start\" font-size=\"10.5\" font-weight=\"600\">OUI</text>\n\n          <!-- Branche NON : primaire, pas d'imagerie urgente (terminal) -->\n          <rect class=\"fb-ok\" x=\"10\" y=\"98\" width=\"290\" height=\"86\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"155\" y=\"118\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Céphalée ancienne / habituelle</text>\n          <text class=\"tx-ok\" x=\"155\" y=\"135\" text-anchor=\"middle\" font-size=\"11\">→ primaire, pas d'imagerie urgente</text>\n          <text class=\"tx-ok\" x=\"155\" y=\"156\" text-anchor=\"middle\" font-size=\"10.5\">Si tableau ≠ migraine sans aura</text>\n          <text class=\"tx-ok\" x=\"155\" y=\"170\" text-anchor=\"middle\" font-size=\"10.5\">typique (ICHD-3) : <span class=\"kw-imagerie\">IRM</span> <span class=\"kw-chiffre\">≥ 1</span>×, sans <span class=\"kw-alerte\">urgence</span></text>\n\n          <!-- Branche OUI : Q2 mode d'installation -->\n          <rect class=\"fb-amber\" x=\"330\" y=\"98\" width=\"220\" height=\"50\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"440\" y=\"119\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Mode d'installation ?</text>\n          <text class=\"tx-amber\" x=\"440\" y=\"136\" text-anchor=\"middle\" font-size=\"11\">(brutale <span class=\"kw-bio\">vs</span> progressive)</text>\n          <line class=\"ln\" x1=\"440\" y1=\"148\" x2=\"440\" y2=\"162\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"200\" y1=\"162\" x2=\"500\" y2=\"162\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"200\" y1=\"162\" x2=\"200\" y2=\"178\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"200,184 195,176 205,176\"/>\n          <line class=\"ln\" x1=\"500\" y1=\"162\" x2=\"500\" y2=\"178\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"500,184 495,176 505,176\"/>\n          <text class=\"tx-muted\" x=\"200\" y=\"174\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">brutale</text>\n          <text class=\"tx-muted\" x=\"500\" y=\"174\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">progressive</text>\n\n          <!-- Brutale : TDM + angio-TDM (HSA) -->\n          <rect class=\"fb-red\" x=\"40\" y=\"186\" width=\"320\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"200\" y=\"208\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Brutale &lt;<span class=\"kw-chiffre\"> 1 h</span> (coup de tonnerre &lt;<span class=\"kw-chiffre\"> 1 min</span>)</text>\n          <text class=\"tx-red\" x=\"200\" y=\"225\" text-anchor=\"middle\" font-size=\"11\"><span class=\"kw-imagerie\">TDM</span> sans injection en urgence (HSA)</text>\n          <text class=\"tx-red\" x=\"200\" y=\"239\" text-anchor=\"middle\" font-size=\"11\">+ <span class=\"kw-imagerie\">angio-TDM</span> cérébrale</text>\n\n          <!-- Progressive : IRM complète (terminal) -->\n          <rect class=\"fb-red\" x=\"370\" y=\"186\" width=\"180\" height=\"86\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"460\" y=\"208\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span class=\"kw-imagerie\">IRM cérébrale</span></text>\n          <text class=\"tx-red\" x=\"460\" y=\"222\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">complète d'emblée</text>\n          <text class=\"tx-red\" x=\"460\" y=\"241\" text-anchor=\"middle\" font-size=\"10.5\">processus expansif,</text>\n          <text class=\"tx-red\" x=\"460\" y=\"255\" text-anchor=\"middle\" font-size=\"10.5\">TVC, <span class=\"kw-etio\">dissection</span></text>\n\n          <!-- Q3 : imagerie normale ? -->\n          <line class=\"ln\" x1=\"200\" y1=\"246\" x2=\"200\" y2=\"262\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"200,268 195,260 205,260\"/>\n          <rect class=\"fb-amber\" x=\"80\" y=\"270\" width=\"240\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"200\" y=\"294\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Imagerie cérébrale normale ?</text>\n          <line class=\"ln\" x1=\"200\" y1=\"310\" x2=\"200\" y2=\"326\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"200,332 195,324 205,324\"/>\n          <text class=\"tx-muted\" x=\"214\" y=\"323\" text-anchor=\"start\" font-size=\"10\" font-weight=\"600\">oui</text>\n\n          <!-- Terminal PL -->\n          <rect class=\"fb-ok\" x=\"60\" y=\"334\" width=\"280\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"200\" y=\"356\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span class=\"kw-ttt\">Ponction</span> lombaire (xanthochromie)</text>\n          <text class=\"tx-ok\" x=\"200\" y=\"373\" text-anchor=\"middle\" font-size=\"10.5\">± <span class=\"kw-imagerie\">angio-IRM</span> / <span class=\"kw-imagerie\">angio-TDM</span> répétée à qq jours</text>\n          <text class=\"tx-ok\" x=\"200\" y=\"387\" text-anchor=\"middle\" font-size=\"10.5\">si suspicion de SVCR</text>\n\n          <!-- Bandeau dogmes -->\n          <rect class=\"fb-grey\" x=\"30\" y=\"420\" width=\"500\" height=\"42\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"439\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">3 dogmes : brutale → HSA · progressive → <span class=\"kw-alerte\">HTIC</span> · fébrile → <span class=\"kw-alerte\">méningite</span></text>\n          <text class=\"tx-grey\" x=\"280\" y=\"454\" text-anchor=\"middle\" font-size=\"10.5\">Examen clinique normal n'élimine PAS une cause grave</text>\n        </svg>\n        <figcaption>Arbre d'indication de l'imagerie devant une céphalée : le drapeau rouge (céphalée récente / inhabituelle / aggravée) ouvre l'exploration en urgence ; le mode d'installation (brutale vs progressive) oriente vers <span class=\"kw-imagerie\">TDM</span> + <span class=\"kw-imagerie\">angio-TDM</span> ou <span class=\"kw-imagerie\">IRM</span> complète d'emblée. Chez l'enfant, l'imagerie cérébrale repose sur la <span class=\"kw-imagerie\">TDM</span> injectée (plus accessible) ou l'<span class=\"kw-imagerie\">IRM</span> (meilleure analyse de la fosse postérieure et de la charnière). Source : fiche source EDN item 100, obj. imagerie.</figcaption>\n      </figure>\n\n      <h4>Stratégie d'imagerie devant une <span class=\"kw-clinique\">céphalée</span> aiguë</h4>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Imagerie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Céphalée <strong>brutale</strong></th>\n            <td><strong><span class=\"kw-imagerie\">TDM cérébrale sans injection</span> en <span class=\"kw-alerte\">urgence</span> :</strong> recherche d'<span class=\"kw-etio\">HSA</span><br><strong><span class=\"kw-imagerie\">Angio-TDM cérébrale</span> systématique :</strong> exploration des réseaux artériel et veineux<br><strong><span class=\"kw-imagerie\">Angio-TDM des TSAO</span> :</strong> si suspicion de <span class=\"kw-etio\">dissection des artères cervico-céphaliques</span> (<span class=\"kw-clinique\">céphalée</span> brutale sans HSA visible)<br><strong><span class=\"kw-imagerie\">IRM + angio-IRM</span> cérébrale et/ou TSAO :</strong> possible en 1ʳᵉ intention si ça ne retarde pas la PEC<br><strong>Si imagerie cérébrale normale :</strong> <span class=\"kw-imagerie\">PL</span> (même si céphalée disparue) en l'absence d'HSA visible ; <span class=\"kw-imagerie\">IRM + ARM ou Angio-TDM répétées</span> quelques jours plus tard si suspicion de <span class=\"kw-etio\">SVCR</span></td>\n          </tr>\n          <tr>\n            <th>Céphalée <strong>progressive</strong> (récente, inhabituelle ou aggravée &lt; 7 j)</th>\n            <td><strong>Recherche d'un processus expansif intracrânien ou d'une cause vasculaire</strong> (<span class=\"kw-etio\">dissection</span>, TVC)<br><strong><span class=\"kw-imagerie\">IRM cérébrale complète</span> d'emblée :</strong> séquences T1, T2, <span class=\"kw-imagerie\">FLAIR</span>, T1 injecté, T2*, <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">IRM</span></span> des TSAO<br><strong>Si <span class=\"kw-imagerie\">IRM</span> non accessible :</strong> 1. <span class=\"kw-imagerie\">TDM cérébrale sans + avec injection</span> + <span class=\"kw-imagerie\">Angio-TDM des TSAO</span> ; 2. <span class=\"kw-imagerie\">IRM</span> réalisée si <span class=\"kw-imagerie\">TDM</span> normale et persistance de la <span class=\"kw-clinique\">céphalée</span> (recherche TVC, PRES, nécroses pituitaires, syndromes d'<span class=\"kw-clinique\">hypotension</span> intracrânienne mal visibles en <span class=\"kw-imagerie\">TDM</span>)<br><strong><span class=\"kw-imagerie\">PL</span></strong> si l'imagerie n'apporte pas de diagnostic et que la céphalée persiste</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Place de l'imagerie devant une <span class=\"kw-clinique\">céphalée</span> chronique</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Indication</th>\n            <td><strong><span class=\"kw-imagerie\">IRM cérébrale</span> sans <span class=\"kw-alerte\">urgence</span>, au moins une fois</strong>, lorsque le diagnostic <strong>ne correspond pas à une <span class=\"kw-def\">migraine</span> sans aura caractéristique</strong> selon l'ICHD-3</td>\n          </tr>\n          <tr>\n            <th>Objectifs selon le tableau</th>\n            <td><strong><span class=\"kw-def\">Migraine</span> avec aura :</strong> rechercher une <span class=\"kw-etio\">malformation artério-veineuse</span> et une <span class=\"kw-etio\">maladie des petites artères cérébrales</span> ; l'<span class=\"kw-imagerie\">IRM</span> montre souvent (<span class=\"kw-chiffre\">40 %</span>) des anomalies de signal non spécifiques en <span class=\"kw-imagerie\">FLAIR</span>/T2 à ne pas confondre avec des lésions démyélinisantes<br><strong>CCQ :</strong> rechercher des signes d'<span class=\"kw-etio\">HTIC ou hypotension intracrânienne chroniques</span> ; rechercher des <span class=\"kw-etio\">tumeurs de la loge hypophysaire / hypothalamique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique — anomalies fortuites en <span class=\"kw-imagerie\">IRM</span>.</strong> En raison du nombre croissant d'<span class=\"kw-imagerie\">IRM</span> demandées, beaucoup d'anomalies sont des <strong>découvertes fortuites qui ne causent pas de <span class=\"kw-clinique\">céphalées</span></strong> : <span class=\"kw-radio\">kystes arachnoïdiens</span>, anomalies veineuses de développement, <span class=\"kw-imagerie\">sinusites chroniques maxillaires et frontales</span>. Ne pas leur attribuer la <span class=\"kw-clinique\">céphalée</span> du patient.\n      </div>\n\n      <h4>Récap de la place de la PL après imagerie</h4>\n      <ul>\n        <li>Suspicion d'<span class=\"kw-etio\">HSA</span> avec imagerie normale (pas avant <span class=\"kw-chiffre\">6 h</span>, fenêtre <span class=\"kw-chiffre\">12 h</span> - <span class=\"kw-chiffre\">14 jours</span>)</li>\n        <li>Suspicion de <span class=\"kw-etio\">méningite infectieuse</span></li>\n        <li>Suspicion d'<span class=\"kw-etio\">HTIC</span> avec imagerie non diagnostique : <strong>mesure de la pression du <span class=\"kw-bio\">LCS</span> en DLG + <span class=\"kw-imagerie\">FO</span></strong></li>\n        <li><span class=\"kw-clinique\">Céphalée</span> aiguë après imagerie sans diagnostic certain</li>\n      </ul>\n\n      <h4>Spécificités de l'imagerie chez l'<strong>enfant</strong></h4>\n      <p>L'intitulé EDN inclut explicitement la pédiatrie. Chez l'enfant, l'imagerie est <strong>plus sélective</strong> qu'à l'adulte (<span class=\"kw-clinique\">irradiation</span> <span class=\"kw-ci\">à éviter</span>, sédation possible pour <span class=\"kw-imagerie\">IRM</span> &lt;<span class=\"kw-chiffre\"> 6 ans</span>), et certains <span class=\"kw-alerte\">drapeaux rouges</span> sont spécifiques.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails pédiatriques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Drapeaux rouges spécifiques</th>\n            <td><span class=\"kw-clinique\">Céphalée occipitale</span> (rare chez l'enfant migraineux, oriente vers la fosse postérieure) ; <span class=\"kw-clinique\">vomissements matinaux</span> isolés ; <span class=\"kw-clinique\">retard scolaire</span> récent ou <span class=\"kw-clinique\">troubles du comportement</span> ; ralentissement statural / cassure de courbe (cause hypothalamo-hypophysaire) ; modification du caractère de la <span class=\"kw-clinique\">céphalée</span> ancienne</td>\n          </tr>\n          <tr>\n            <th>Risque selon l'âge</th>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 6 ans</span> :</strong> <span class=\"kw-alerte\">tumeur de la fosse postérieure</span> surreprésentée (médulloblastome, astrocytome pilocytique) → seuil d'imagerie abaissé<br><strong>Adolescent :</strong> profil plus proche de l'adulte ; <span class=\"kw-etio\">HTIC idiopathique</span> à évoquer (jeune fille en surpoids)</td>\n          </tr>\n          <tr>\n            <th>Choix de la modalité</th>\n            <td><strong><span class=\"kw-imagerie\">IRM cérébrale</span> = examen de référence</strong> (pas d'<span class=\"kw-clinique\">irradiation</span>, meilleure résolution fosse postérieure)<br><strong><span class=\"kw-imagerie\">TDM</span></strong> réservée à l'<span class=\"kw-alerte\">urgence</span> vitale si <span class=\"kw-imagerie\">IRM</span> non accessible (HSA suspectée, TC récent)</td>\n          </tr>\n          <tr>\n            <th>Pas d'imagerie systématique si</th>\n            <td>Tableau de <span class=\"kw-def\">migraine</span> typique avec examen neurologique normal + croissance normale + pas de <span class=\"kw-alerte\">drapeau rouge</span> → diagnostic clinique, <span class=\"kw-def\">surveillance</span> simple</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 340 — <span class=\"kw-etio\">AVC</span></em></p>","frequence":3},{"id":"100-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de traitement et de prise en charge des céphalées primaires en dehors du contexte de l’urgence","contenu":"<p>La PEC détaillée des <span class=\"kw-clinique\">céphalées</span> primaires (<span class=\"kw-def\">migraine</span>, AVF, névralgie du V) est traitée dans l'<strong>item 99</strong>. L'item 100 retient les <strong>principes généraux</strong> communs et les particularités liées à la CCQ et à l'abus <span class=\"kw-etio\">médicamenteux</span>.</p>\n\n      <h4>Principes généraux de PEC d'une <span class=\"kw-clinique\">céphalée</span> primaire</h4>\n      <ul>\n        <li><strong>Traitement de crise :</strong> isoler au calme ; antalgie adaptée (<span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">AINS</span>, triptans en cas de <span class=\"kw-def\">migraine</span>) ; antiémétique si besoin (<span class=\"kw-ttt\">métoclopramide</span>)</li>\n        <li><strong>Traitement de fond :</strong> indiqué si crises fréquentes ou invalidantes ; molécules variant selon la cause (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">topiramate</span>, <span class=\"kw-ttt\">amitriptyline</span>… détail dans l'item 99)</li>\n        <li><strong>Mesures non médicamenteuses :</strong> <span class=\"kw-clinique\">agenda des crises</span> (incontournable pour repérer les déclencheurs et l'abus) ; éviction des facteurs déclenchants ; <span class=\"kw-clinique\">exercice physique</span> ; <span class=\"kw-clinique\">physiothérapie</span> ; psychothérapie de soutien, TCC, relaxation</li>\n        <li><strong>Information du patient :</strong> caractère chronique, bénin mais invalidant ; pas d'examens en routine si tableau caractéristique</li>\n      </ul>\n\n      <h4>PEC spécifique de la <span class=\"kw-clinique\">céphalée</span> chronique quotidienne (CCQ)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-ttt\">Sevrage</span> <span class=\"kw-etio\">médicamenteux</span></th>\n            <td><strong>Indispensable</strong> en cas d'abus associé (<span class=\"kw-chiffre\">80 %</span> des CCQ) ; le plus souvent en ambulatoire ; progressif ou brutal selon le médicament<br>On stoppe le médicament en cause ; on peut en proposer un autre avec la consigne de <strong>ne pas dépasser 8 j/mois</strong> de prise régulière</td>\n          </tr>\n          <tr>\n            <th>Traitement de fond</th>\n            <td><strong>Signes migraineux</strong> associés (photophobie, <span class=\"kw-clinique\">nausées</span>, pulsatilité) → traiter comme une <span class=\"kw-def\">migraine chronique</span> : <span class=\"kw-ttt\">topiramate</span><br><strong>Type tensive pure</strong> → <span class=\"kw-ttt\">amitriptyline</span></td>\n          </tr>\n          <tr>\n            <th>Non <span class=\"kw-etio\">médicamenteux</span></th>\n            <td><span class=\"kw-clinique\">Exercice physique</span> ; <span class=\"kw-clinique\">physiothérapie</span> ; PEC psychologique (psychothérapie de soutien, TCC, relaxation) en <strong>complément</strong> du traitement <span class=\"kw-etio\">médicamenteux</span></td>\n          </tr>\n          <tr>\n            <th>Information</th>\n            <td>La <span class=\"kw-clinique\">céphalée</span> primaire sous-jacente <strong>persistera</strong> malgré le <span class=\"kw-ttt\">sevrage</span><br>Le sevrage entraîne une <span class=\"kw-alerte\">céphalée rebond</span> (recrudescence intense temporaire) à prendre en charge par mesures non médicamenteuses et un traitement de crise <strong>différent</strong> de celui surconsommé</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Suivi</span></th>\n            <td>Tenue d'un <strong>agenda des crises</strong> pour <span class=\"kw-def\">surveillance</span> rapprochée du <span class=\"kw-ttt\">sevrage</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Nuance importante.</strong> Le rôle de la surconsommation d'<span class=\"kw-ttt\">antalgiques</span> dans l'apparition d'une <span class=\"kw-def\">migraine</span> chronique ne doit <strong>pas être surestimé</strong> — cette attitude peut conduire à <span class=\"kw-alerte\">stigmatiser les patients</span> comme responsables de leur maladie et privilégier le <span class=\"kw-ttt\">sevrage</span> au détriment d'autres solutions thérapeutiques plus efficientes.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":0}],"astuces":[{"type":"danger","titre":"Coup de tonnerre = HSA jusqu'à preuve du contraire","contenu":"Toute céphalée <strong>brutale</strong> atteignant son intensité maximale en <strong>&lt; 1 minute</strong> = <strong>hémorragie sous-arachnoïdienne</strong> (anévrysme rompu) jusqu'à preuve du contraire. <strong>TDM cérébrale sans injection en urgence</strong> (sensibilité ~100 % si &lt; 6 h). Si TDM normale et clinique évocatrice → <strong>PL</strong> (xanthochromie après 12 h). Ne jamais rassurer hâtivement."},{"type":"danger","titre":"Horton — corticoïdes sans attendre la biopsie","contenu":"Devant une céphalée temporale chez un patient &gt; <strong>50 ans</strong> + <strong>VS/CRP élevées</strong> + signes évocateurs (claudication mâchoire, hyperesthésie cuir chevelu, AEG), démarrer la <strong>corticothérapie immédiatement</strong> (1 mg/kg/j ou bolus 500–1000 mg si atteinte oculaire), sans attendre la biopsie d'artère temporale. Risque = <strong>cécité monoculaire définitive</strong> (NOIAA) en quelques heures."},{"type":"info","titre":"Mnémo SNOOP4 — les drapeaux rouges à toujours rechercher","contenu":"<strong>S</strong>ystemic (fièvre, AEG, cancer, VIH) · <strong>N</strong>eurological (focal, confusion, œdème papillaire) · <strong>O</strong>nset sudden (coup de tonnerre) · <strong>O</strong>lder (1ʳᵉ céphalée &gt; 50 ans) · <strong>P</strong>attern change / <strong>P</strong>ostural / <strong>P</strong>recipitated by Valsalva / <strong>P</strong>regnancy. Présence d'un seul drapeau = imagerie en urgence."},{"type":"warn","titre":"Céphalée orthostatique post-PL — penser hypotension du LCS","contenu":"Céphalée apparaissant en <strong>position debout</strong> et disparaissant en <strong>décubitus</strong>, après une PL ou spontanément (brèche dure-mérienne) = <strong>hypotension intracrânienne</strong>. Traitement : décubitus, hydratation, caféine ; si persistance &gt; 24–48 h → <strong>blood patch</strong> par l'anesthésiste. À ne pas confondre avec une céphalée par HIC (aggravée par le décubitus, vomissements matinaux)."},{"type":"info","titre":"Migraine de l'enfant — sieste et ibuprofène","contenu":"Chez l'enfant, la migraine est souvent <strong>bilatérale</strong>, <strong>plus courte</strong> (≥ 1 h), avec <strong>vomissements et douleurs abdominales</strong> au premier plan. Le traitement de crise repose sur l'<strong>ibuprofène 10 mg/kg</strong> + <strong>sieste au calme</strong> dans l'obscurité. Triptans nasaux à partir de 12 ans. Toujours éliminer une cause secondaire (tumeur de fosse postérieure ++) si drapeaux rouges."}],"strategie":{"urgence":"<p><strong>Urgences vitales — à reconnaître d'emblée</strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale</span> sans délai ± <span class=\"kw-bio\">ponction lombaire</span></p><ul><li><span class=\"kw-alerte\">Syndrome méningé</span> fébrile = <span class=\"kw-etio\">méningite</span> jusqu'à preuve du contraire ; <span class=\"kw-clinique\">purpura</span> → <span class=\"kw-etio\">méningocoque</span> (<span class=\"kw-alerte\">urgence</span> absolue)</li><li><span class=\"kw-alerte\">Syndrome méningé</span> non fébrile = <span class=\"kw-etio\">HSA</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Syndrome d'HTIC</span> : <span class=\"kw-clinique\">céphalée</span> progressive + <span class=\"kw-clinique\">vomissements</span> + <span class=\"kw-clinique\">œdème papillaire</span> ± troubles de vigilance</li></ul><p><strong>À prendre en charge en <span class=\"kw-alerte\">urgence</span> <span class=\"q\">(&lt; quelques heures)</span></strong></p><ul><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">brutale</span> : maximale en <span class=\"kw-chiffre\">&lt; 1 h</span>, « coup de tonnerre » en <span class=\"kw-chiffre\">&lt; 1 min</span></li><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-clinique\">inhabituelle et récente</span> ou d'aggravation récente <span class=\"kw-chiffre\">&lt; 7 jours</span></li><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">fébrile</span> (sauf cause générale évidente, ex. syndrome grippal en période épidémique)</li><li><span class=\"kw-clinique\">Céphalée</span> + <span class=\"kw-clinique\">signes neurologiques</span> (focaux, confusion, crise comitiale)</li><li>Suspicion d'<span class=\"kw-etio\">intoxication au CO</span> (chauffage défectueux, plusieurs personnes du foyer touchées)</li><li><span class=\"kw-def\">Terrain</span> d'<span class=\"kw-clinique\">immunodépression</span> (<span class=\"kw-etio\">VIH</span> non contrôlé, transplanté, <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul><p><strong>Délais clés des examens</strong></p><ul><li><span class=\"kw-imagerie\">TDM</span> sans injection : sensibilité HSA ~<span class=\"kw-chiffre\">100 %</span> à <span class=\"kw-chiffre\">6 h</span>, chute à ~<span class=\"kw-chiffre\">80 %</span> à <span class=\"kw-chiffre\">24 h</span> et ~<span class=\"kw-chiffre\">50 %</span> à <span class=\"kw-chiffre\">1 semaine</span></li><li><span class=\"kw-bio\">PL</span> : pas avant <span class=\"kw-chiffre\">6 h</span> (apparition de la <span class=\"kw-bio\">xanthochromie</span>), fenêtre utile <span class=\"kw-chiffre\">12 h - 14 jours</span></li><li><span class=\"kw-imagerie\">Angio-TDM / angio-IRM</span> répétée à <span class=\"kw-chiffre\">quelques jours</span> si suspicion de <span class=\"kw-etio\">SVCR</span> (sténoses maximales à <span class=\"kw-chiffre\">2 semaines</span>)</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">SAU</span> / <span class=\"kw-alerte\">urgence</span> :</strong> toute <span class=\"kw-clinique\">céphalée</span> <span class=\"kw-alerte\">brutale</span>, <span class=\"kw-clinique\">inhabituelle et récente</span> (<span class=\"kw-chiffre\">&lt; 7 j</span>), <span class=\"kw-alerte\">fébrile</span>, avec <span class=\"kw-clinique\">signes neurologiques</span> ou sur <span class=\"kw-clinique\">immunodépression</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-alerte\">céphalée secondaire grave</span> établie (poursuite du bilan + traitement étiologique) ; ou diagnostic non établi avec <span class=\"kw-clinique\">céphalée intense persistante</span>.<br><strong>RAD possible :</strong> patient soulagé et exploration normale (<span class=\"kw-chiffre\">30-70 %</span> des bilans sont normaux) ; un <strong>1ᵉʳ épisode</strong> ne permet aucun diagnostic de céphalée primaire (recul temporel + plusieurs crises nécessaires).<br><strong>Consultation simple :</strong> céphalée connue ne cédant pas au traitement habituel ; semi-récente (<span class=\"kw-chiffre\">8 j - 6 mois</span>) sans aggravation ; ancienne (<span class=\"kw-chiffre\">≥ 6 mois</span>) difficile à gérer.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">brutale / en coup de tonnerre</span> → <span class=\"kw-etio\">HSA</span> (± autres causes vasculaires)</li><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">progressive</span> ou provoquée par <span class=\"kw-clinique\">toux / effort / Valsalva</span> → <span class=\"kw-etio\">processus expansif intracrânien</span> / <span class=\"kw-etio\">HTIC</span></li><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">fébrile</span> + <span class=\"kw-clinique\">raideur de nuque</span> → <span class=\"kw-etio\">méningite</span> ; <span class=\"kw-clinique\">purpura</span> → <span class=\"kw-etio\">méningocoque</span></li><li><span class=\"kw-clinique\">Déficit neurologique focal</span> ou <span class=\"kw-clinique\">crise comitiale</span> → cause secondaire (<span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">TVC</span>, tumeur, <span class=\"kw-etio\">SVCR</span> compliqué)</li><li><span class=\"kw-alerte\">Trouble de la vigilance</span>, <span class=\"kw-clinique\">modification du caractère</span> ou troubles mnésiques → cause secondaire</li><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">modifiée par la posture</span> : aggravée allongé → <span class=\"kw-etio\">HTIC</span> ; aggravée debout → <span class=\"kw-etio\">hypotension intracrânienne</span></li><li>Début après <span class=\"kw-chiffre\">50 ans</span> ± <span class=\"kw-clinique\">AEG</span> / <span class=\"kw-clinique\">claudication de la mâchoire</span> → <span class=\"kw-etio\">artérite à cellules géantes</span> (Horton)</li><li><span class=\"kw-clinique\">Céphalée</span> après <span class=\"kw-clinique\">traumatisme crânien</span> → <span class=\"kw-etio\">hématome sous-dural</span> ; <span class=\"kw-clinique\">amaigrissement</span> → cause secondaire</li><li>Toute <span class=\"kw-alerte\">modification d'une céphalée ancienne</span> → suspecter une cause secondaire surajoutée</li><li>Enfant : <span class=\"kw-clinique\">vomissements matinaux</span>, <span class=\"kw-clinique\">céphalée occipitale</span>, cassure de la courbe → <span class=\"kw-alerte\">tumeur de la fosse postérieure</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">céphalée</span> <span class=\"kw-alerte\">récente + inhabituelle</span> est <span class=\"kw-etio\">secondaire</span> jusqu'à preuve du contraire (examens en <span class=\"kw-alerte\">urgence</span>) ; toute céphalée <span class=\"kw-clinique\">ancienne + habituelle</span> est <span class=\"kw-etio\">primaire</span> (PEC sans urgence).<br><strong>3 dogmes d'exploration :</strong> céphalée <span class=\"kw-alerte\">brutale</span> → <span class=\"kw-etio\">HSA</span> · <span class=\"kw-alerte\">progressive</span> → <span class=\"kw-etio\">HTIC</span> · <span class=\"kw-alerte\">fébrile</span> → <span class=\"kw-etio\">méningite</span>.</p><p><strong>Traitement aux urgences — <span class=\"kw-clinique\">céphalée</span> récente inhabituelle</strong></p><ul><li><span class=\"kw-ttt\">Traitement étiologique</span> avant tout (selon la cause identifiée)</li><li>Antalgie <span class=\"kw-ttt\">IV</span> si troubles digestifs : <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">néfopam</span> + antiémétique <span class=\"kw-ttt\">métoclopramide</span></li><li><span class=\"kw-ci\">Éviter AINS / aspirine</span> tant que le diagnostic n'est pas posé (risque d'aggraver une <span class=\"kw-etio\">HSA</span> / un <span class=\"kw-etio\">AVC hémorragique</span>)</li></ul><p><strong>Traitement de crise — <span class=\"kw-clinique\">céphalée</span> primaire connue</strong></p><ul><li>Isoler le patient au calme (chambre sombre, silencieuse) ; réhydratation si besoin</li><li>Antalgie <span class=\"kw-ttt\">IV</span> : <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">néfopam</span>, <span class=\"kw-ttt\">kétoprofène</span> (<span class=\"kw-ttt\">AINS</span> autorisé une fois le diagnostic primaire posé) + <span class=\"kw-ttt\">métoclopramide</span></li></ul><p><strong>CCQ avec abus <span class=\"kw-etio\">médicamenteux</span> <span class=\"q\">(<span class=\"kw-chiffre\">80 %</span> des CCQ de longue durée)</span></strong></p><ul><li><span class=\"kw-ttt\">Sevrage</span> du médicament en cause (le plus souvent ambulatoire) ; consigne : ne pas dépasser <span class=\"kw-chiffre\">8 j/mois</span> de prise régulière</li><li>Traitement de fond : <span class=\"kw-ttt\">topiramate</span> (profil migraineux) ou <span class=\"kw-ttt\">amitriptyline</span> (<span class=\"kw-clinique\">céphalée</span> de tension pure)</li><li>Prévenir la <span class=\"kw-alerte\">céphalée rebond</span> au <span class=\"kw-ttt\">sevrage</span> ; traitement de crise <strong>différent</strong> de celui surconsommé ; mesures non médicamenteuses associées</li></ul>","suivi":"<p><strong>Outil clé :</strong> <span class=\"kw-clinique\">agenda des crises</span> — repère les déclencheurs, dépiste l'<span class=\"kw-alerte\">abus médicamenteux</span> et juge l'efficacité des traitements.<br><strong>Après bilan normal :</strong> un 1ᵉʳ épisode ne permet pas de poser un diagnostic de <span class=\"kw-clinique\">céphalée</span> primaire ; <span class=\"kw-def\">réévaluation</span> à distance (recul + plusieurs crises nécessaires).<br><strong>CCQ / <span class=\"kw-ttt\">sevrage</span> :</strong> <span class=\"kw-def\">surveillance</span> rapprochée ; la céphalée primaire sous-jacente <span class=\"kw-clinique\">persiste</span> malgré le sevrage ; non <span class=\"kw-etio\">médicamenteux</span> (<span class=\"kw-clinique\">exercice physique</span>, physiothérapie, TCC, relaxation).<br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">IRM</span> au moins une fois pour toute CCQ ; ne pas attribuer la céphalée à une <span class=\"kw-imagerie\">anomalie fortuite</span> (kystes arachnoïdiens, sinusites chroniques, anomalies veineuses de développement).<br><strong>Nuance :</strong> ne pas <span class=\"kw-alerte\">surestimer</span> le rôle de l'abus médicamenteux ni stigmatiser le patient comme responsable de sa maladie.</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant","label":"Collège CEN — Céphalée inhabituelle aiguë & chronique"},{"href":"https://www.cen-neurologie.fr/second-cycle/migraine-nevralgie-du-trijumeau-et-algies-de-la-face","label":"Collège CEN — Migraine, névralgie du trijumeau & algies de la face"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/neurologie/cephalee-aigue-chronique","label":"Collège Pédiatrie — Céphalée aiguë & chronique"},{"href":"https://campus.neurochirurgie.fr/article1715.html","label":"Campus Neurochirurgie — Névralgie du trijumeau"},{"href":"https://www.chu-caen.fr/wp-content/uploads/2022/12/Fiche-dinformation-nevralgie-dArnold.pdf","label":"CHU Caen — Névralgie d'Arnold (PDF patient)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Céphalée à explorer — Première question : drapeau rouge faisant suspecter une cause secondaire ?","detail":"<h4>CAT — indication de l'imagerie devant une <span class=\"kw-clinique\">céphalée</span> — 3 dogmes : brutale → HSA · progressive → <span class=\"kw-alerte\">HTIC</span> · fébrile → <span class=\"kw-alerte\">méningite</span></h4>","branches":[{"to":"t-primaire","label":"Ancienne et habituelle, sans drapeau rouge","color":"green"},{"to":"q-installation","label":"Récente, inhabituelle ou aggravée < 7 j = suspicion de cause secondaire","color":"red"}]},{"id":"t-primaire","kind":"terminal","label":"Céphalée primaire → pas d'imagerie en urgence","color":"green","detail":"<h4>Raisonnement</h4><ul><li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-clinique\">ancienne et habituelle</span> = <span class=\"kw-etio\">primaire</span> ; prise en charge sans <span class=\"kw-alerte\">urgence</span>. Toute <span class=\"kw-alerte\">modification d'une céphalée ancienne</span> ferait au contraire suspecter une cause secondaire.</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> sans <span class=\"kw-alerte\">urgence</span>, au moins une fois, uniquement si le tableau <strong>ne correspond pas à une <span class=\"kw-def\">migraine sans aura</span> caractéristique</strong> (ICHD-3) — et systématiquement devant toute <span class=\"kw-def\">CCQ</span>.</li></ul><h4>Piège</h4><ul><li>Ne pas attribuer la <span class=\"kw-clinique\">céphalée</span> à une <span class=\"kw-imagerie\">anomalie fortuite</span> d'<span class=\"kw-imagerie\">IRM</span> (kystes arachnoïdiens, anomalies veineuses de développement, sinusites chroniques).</li></ul><h4>Renvoi</h4><ul><li>Item 99 (Migraine - névralgie du trijumeau - algie de la face)</li></ul>"},{"id":"q-installation","kind":"decision","label":"Mode d'installation de la <span class=\"kw-clinique\">céphalée</span> ? — Brutale (max <span class=\"kw-chiffre\">< 1</span> h, coup de tonnerre < <span class=\"kw-chiffre\">1 min</span>) <span class=\"kw-bio\">vs</span> progressive","branches":[{"to":"t-irm","label":"Progressive","color":"amber"},{"to":"q-imagerie","label":"Brutale / coup de tonnerre","color":"red"}]},{"id":"t-irm","kind":"terminal","label":"IRM cérébrale complète d'emblée","color":"amber","detail":"<h4>Objectif</h4><ul><li>Rechercher un <span class=\"kw-alerte\">processus expansif intracrânien</span> ou une cause vasculaire (<span class=\"kw-etio\">thrombose veineuse cérébrale</span>, <span class=\"kw-etio\">dissection</span>).</li></ul><h4>Modalités</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale complète</span> : T1, T2, <span class=\"kw-imagerie\">FLAIR</span>, T1 injecté, T2*, <span class=\"kw-imagerie\">angio-IRM des TSAO</span></li><li>Si <span class=\"kw-imagerie\">IRM</span> non accessible : <span class=\"kw-imagerie\">TDM</span> sans puis avec injection + <span class=\"kw-imagerie\">angio-TDM des TSAO</span>, puis <span class=\"kw-imagerie\">IRM</span> si <span class=\"kw-imagerie\">TDM</span> normale et <span class=\"kw-clinique\">céphalée</span> persistante</li></ul><h4><span class=\"kw-ttt\">Ponction</span> lombaire</h4><ul><li><span class=\"kw-bio\">PL</span> si l'imagerie n'apporte pas de diagnostic et que la <span class=\"kw-clinique\">céphalée</span> persiste (mesure de pression du <span class=\"kw-bio\">LCS</span> si suspicion d'<span class=\"kw-etio\">HTIC</span>).</li></ul><h4>Enfant</h4><ul><li><span class=\"kw-imagerie\">IRM</span> = examen de référence (pas d'<span class=\"kw-clinique\">irradiation</span>, meilleure analyse de la fosse postérieure) ; <span class=\"kw-imagerie\">TDM</span> réservée à l'<span class=\"kw-alerte\">urgence</span> vitale.</li></ul><h4>Renvoi</h4><ul><li>Item 195 (Artérite à cellules géantes) · 151 (Méningite)</li></ul>"},{"id":"q-imagerie","kind":"decision","label":"TDM sans injection + angio-TDM en urgence → imagerie normale ? — TDM sans injection (recherche d'HSA) + angio-TDM systématique (réseaux artériel et veineux)","branches":[{"to":"t-tdm","label":"Anormale (HSA, hémorragie, dissection… visibles)","color":"red"},{"to":"t-pl","label":"Normale","color":"green"}]},{"id":"t-tdm","kind":"terminal","label":"TDM + angio-TDM contributives → diagnostic établi","color":"red","detail":"<h4>Diagnostics retrouvés</h4><ul><li><span class=\"kw-etio\">HSA</span> / <span class=\"kw-etio\">hémorragie intracrânienne</span></li><li><span class=\"kw-etio\">Infarctus cérébral</span> (visible <span class=\"kw-chiffre\">> 3 h</span>)</li><li><span class=\"kw-etio\">Dissection des artères cervico-céphaliques</span> (<span class=\"kw-imagerie\">angio-TDM</span> des TSAO)</li><li><span class=\"kw-etio\">Tumeur cérébrale</span> (rare cause de <span class=\"kw-clinique\">céphalée</span> brutale)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Traitement étiologique</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-alerte\">hospitalisation</span> pour poursuite du bilan.</li></ul><h4>Renvoi</h4><ul><li>Item 341 (Hémorragie méningée) · 340 (<span class=\"kw-alerte\">AVC</span>)</li></ul>"},{"id":"t-pl","kind":"terminal","label":"Ponction lombaire (xanthochromie)","color":"blue","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Céphalée</span> brutale + <span class=\"kw-imagerie\">TDM normale</span> → <span class=\"kw-bio\">PL</span> même si la céphalée a disparu, à la recherche de <span class=\"kw-bio\">xanthochromie</span> + GR (HSA non vue au <span class=\"kw-imagerie\">scanner</span>).</li></ul><h4>Délai</h4><ul><li><span class=\"kw-bio\">PL</span> pas avant <span class=\"kw-chiffre\">6 h</span> (apparition de la xanthochromie) ; fenêtre utile <span class=\"kw-chiffre\">12 h - 14 jours</span>.</li></ul><h4>Compléter</h4><ul><li><span class=\"kw-imagerie\">IRM + ARM</span> ou <span class=\"kw-imagerie\">angio-TDM</span> répétée à <span class=\"kw-chiffre\">quelques jours</span> si suspicion de <span class=\"kw-etio\">SVCR</span> (la 1ʳᵉ <span class=\"kw-imagerie\">angiographie</span> peut être normale &lt; 7 j, sténoses maximales à<span class=\"kw-chiffre\"> 2 semaines</span>).</li></ul><h4>Renvoi</h4><ul><li>Item 341 (Hémorragie méningée)</li></ul>"}]},"cards":[]};